-	// Bounded path: poll a non-blocking lock until acquired or ctx is done.
+	staleInodeRetries := 0
@@ -81,0 +100,4 @@ func lockFile(ctx context.Context, f *os.File) (release func(), err error) {
+		f, err := open()
+		if err != nil {
+			return nil, fmt.Errorf("open flock: %w", err)
+		}
