+			current, err := holdsCurrent(f)
+			if err != nil {
+				_ = f.Close()
+				return nil, err
+			}
+			if current {
+				return func() { _ = f.Close() }, nil
+			}
@@ -88,3 +115,5 @@ func lockFile(ctx context.Context, f *os.File) (release func(), err error) {
-			return nil, fmt.Errorf("flock: %w", lockErr)
-		}
-		if err := ctx.Err(); err != nil {
+			staleInodeRetries++
+			if staleInodeRetries >= 3 {
+				return nil, errors.New("flock path changed while acquiring lock")
+			}
+		} else {
@@ -92 +121,3 @@ func lockFile(ctx context.Context, f *os.File) (release func(), err error) {
-			return nil, fmt.Errorf("flock: %w", err)
+			if !errors.Is(lockErr, syscall.EWOULDBLOCK) {
+				return nil, fmt.Errorf("flock: %w", lockErr)
+			}
@@ -94,5 +125,23 @@ func lockFile(ctx context.Context, f *os.File) (release func(), err error) {
-		select {
-		case <-ctx.Done():
-			_ = f.Close()
-			return nil, fmt.Errorf("flock: %w", ctx.Err())
-		case <-time.After(pollInterval):
+		if err := waitForRetry(ctx); err != nil {
+			return nil, err
+		}
+	}
+}
+
+func waitForRetry(ctx context.Context) error {
+	if err := ctx.Err(); err != nil {
+		return fmt.Errorf("flock: %w", err)
+	}
+	select {
+	case <-ctx.Done():
+		return fmt.Errorf("flock: %w", ctx.Err())
+	case <-time.After(pollInterval):
+		return nil
+	}
+}
+
+func holdsCurrentPathInode(f *os.File, path string) (bool, error) {
+	pathInfo, err := os.Stat(path)
+	if err != nil {
+		if os.IsNotExist(err) {
+			return false, nil
@@ -99,0 +149,28 @@ func lockFile(ctx context.Context, f *os.File) (release func(), err error) {
+		return false, fmt.Errorf("stat flock path: %w", err)
+	}
+	return sameInode(f, pathInfo, "path")
+}
+
+func holdsCurrentRootInode(f *os.File, root *os.Root, name string) (bool, error) {
+	pathInfo, err := osroot.LstatNoSymlinks(root, name)
+	if err != nil {
+		if os.IsNotExist(err) {
+			return false, nil
+		}
+		return fa

