+            foreach ($existing in $found) {
+                if (Test-SamePath -Left $existing.Source -Right $candidate) {
+                    $known = $true
+                    break
+                }
+            }
+            if (-not $known) {
+                $found += [pscustomobject]@{ Source = $candidate }
+            }
+        }
+    }
+    Write-Output -NoEnumerate -InputObject $found
+}
