+			name:    "Windows AppData",
+			goos:    "windows",
+			home:    `C:\Users\tester`,
+			appData: `C:\Users\tester\AppData\Roaming`,
+			want:    filepath.Join(`C:\Users\tester\AppData\Roaming`, "GitHub CLI"),
+		},
